do $$ begin if not exists (select 1 from pg_enum where enumtypid = (select oid from pg_type where typname = 'app_permission' and nspname = 'rbac') and enumlabel = 'tasbih.read') then alter type rbac.app_permission add value 'tasbih.read'; alter type rbac.app_permission add value 'tasbih.create'; alter type rbac.app_permission add value 'tasbih.delete'; alter type rbac.app_permission add value 'bookmarks.read'; alter type rbac.app_permission add value 'bookmarks.create'; alter type rbac.app_permission add value 'bookmarks.delete'; alter type rbac.app_permission add value 'journal.read'; alter type rbac.app_permission add value 'journal.create'; alter type rbac.app_permission add value 'journal.update'; alter type rbac.app_permission add value 'journal.delete'; end if; end$$;
